using System.Security.Claims;using LocalPro.Web.Data;using LocalPro.Web.Domain;using LocalPro.Web.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;
namespace LocalPro.Web.Pages.Requests;
[Authorize][RequestSizeLimit(5*1024*1024)]public class NewModel(AppDbContext db,RequestService service,ConfigurationService config):PageModel{
 [BindProperty(SupportsGet=true)]public int? EditId{get;set;}
 [BindProperty(SupportsGet=true)]public int Category{get;set;}public Domain.Category Selected{get;set;}=null!;
 [BindProperty]public string Description{get;set;}="";[BindProperty]public string Address{get;set;}="";[BindProperty]public string City{get;set;}="Garowe";
 [BindProperty]public string When{get;set;}="Now";[BindProperty]public string Payment{get;set;}="MobileMoney";[BindProperty]public IFormFile? Photo{get;set;}
 public async Task<IActionResult> OnGetAsync(){City=(await config.Get()).City;if(EditId.HasValue){try{var request=await service.Get(User,EditId.Value);if(request.CustomerId!=User.FindFirstValue(ClaimTypes.NameIdentifier)||request.Status!=ServiceRequestStatus.Received&&request.Status!=ServiceRequestStatus.Assigned)return Forbid();Category=request.CategoryId;Description=request.Description;Address=request.Address;City=request.City;When=request.When;Payment=request.PaymentPreference;}catch(RuleException){return NotFound();}}Selected=(await db.Categories.SingleOrDefaultAsync(c=>c.Id==Category&&c.Active))!;return Selected==null?RedirectToPage("/Services"):Page();}
 public async Task<IActionResult> OnPostAsync(){Selected=(await db.Categories.SingleOrDefaultAsync(c=>c.Id==Category&&c.Active))!;if(Selected==null)return RedirectToPage("/Services");try{if(!ModelState.IsValid)return Page();if(EditId.HasValue){await service.Edit(User,EditId.Value,new(Category,Description,Address,City,When,Payment));return RedirectToPage("Track",new{id=EditId.Value});}string? photo=null;if(Photo!=null){if(Photo.Length>3*1024*1024)throw new RuleException("Sawirku waa inuu ka yar yahay 3 MB.");using var ms=new MemoryStream();await Photo.CopyToAsync(ms);photo=Convert.ToBase64String(ms.ToArray());}var request=await service.Create(User,new(Category,Description,Address,City,When,Payment,photo,Photo?.ContentType));return RedirectToPage("Track",new{id=request.Id});}catch(RuleException ex){ModelState.AddModelError("",ex.Message);return Page();}}
}
